/**
 * Art paths for the Min Hero pack.
 *
 * `data/assets.json` is generated by `scripts/import-assets.mjs`; every path is
 * relative (`./assets/...`) so it resolves the same way as the type icons on a
 * static host, a GitHub Pages subpath, `file://`, and an installed PWA.
 *
 * The game art is © ToyChestGames and used with permission (see
 * `public/assets/ATTRIBUTION.md`).
 */

import assetsJson from './data/assets.json';

export interface AssetManifest {
  generatedFrom: string;
  attribution: string;
  /** Minion id → sprite path. */
  minions: Record<string, string>;
  /** Move icon name (`moveIcon_*`) → icon path. */
  moves: Record<string, string>;
  /** UI texture key → path. */
  ui: Record<string, string>;
  stats: {
    minionSprites: number;
    moveIcons: number;
    uiTextures: number;
    bytes: number;
  };
}

export const ASSET_MANIFEST = assetsJson as unknown as AssetManifest;

export const MINION_SPRITE_BY_ID: ReadonlyMap<string, string> = new Map(
  Object.entries(ASSET_MANIFEST.minions),
);

export const MOVE_ICON_BY_NAME: ReadonlyMap<string, string> = new Map(
  Object.entries(ASSET_MANIFEST.moves),
);

export const UI_ASSETS: Readonly<Record<string, string>> = ASSET_MANIFEST.ui;

/** Sprite path for a minion, or `null` when the manifest has no art for it. */
export function minionSpritePath(minionId: string): string | null {
  return MINION_SPRITE_BY_ID.get(minionId) ?? null;
}

/**
 * Icon path for a move. Accepts either the stored `moveIcon_*` name or the bare
 * icon stem, so callers can pass `move.icon` or a hand-written name.
 */
export function moveIconPath(icon: string | null | undefined): string | null {
  if (!icon) return null;
  const direct = MOVE_ICON_BY_NAME.get(icon);
  if (direct) return direct;
  return MOVE_ICON_BY_NAME.get(`moveIcon_${icon}`) ?? null;
}

/** UI texture path; the key set is generated by the asset importer. */
export function uiAsset(key: string): string | null {
  return UI_ASSETS[key] ?? null;
}
